import {Sparkles,Plus,PanelLeftClose,PanelLeftOpen,Folder,FolderPlus,MessageSquare,Search,Grid2X2,Clock3,BookOpen,Settings2,ArrowUp,ChevronDown,ChevronRight,MoreHorizontal,Star,ExternalLink,Copy,GitBranch,Trash2,Download,Eye,Code2,History,RefreshCw,Check,CheckCheck,X,Square,Play,Pause,Bell,FileCode2,Globe,KeyRound,ArrowLeft,LoaderCircle,AlertCircle,CheckCircle2,ArchiveRestore,Link2,Upload,Database,SlidersHorizontal,ArrowUpRight,Command,Layers,Monitor,Smartphone,LayoutTemplate} from 'lucide-react';
