 {page==='schedules'&&!chat&&<section className="page-section"><div className="page-heading"><div><span className="overline">YOUR CHAT, ON A SCHEDULE</span><h1>定时任务</h1><p>让重复的检查，按时发生在对话里。</p></div><button className="button primary" onClick={()=>setScheduleEdit('new')}><Plus size={16}/>创建任务</button></div><div className="info-banner"><Clock3 size={17}/><span>页面打开时自动检查并汇报。关闭期间不执行，重新打开后提示错过的任务；不会自动改代码或发布。</span></div>{state.schedules.length?<div className="schedule-list">{state.schedules.map(t=><article className="schedule-card" key={t.id}><div className={'schedule-symbol '+(t.paused?'paused':'')}><Clock3 size={22}/></div><div className="schedule-info"><div><h3>{t.name}</h3><span className={'pill '+(t.paused?'neutral':'')}>{t.paused?'已暂停':'已启用'}</span></div><p>{t.prompt}</p><small>{frequencyNames[t.frequency]} · {t.at} · {t.timezone}<span>下次：{t.paused?'暂停中':new Date(t.next).toLocaleString('zh-CN',{timeZone:t.timezone})}</span></small></div><div className="schedule-actions"><button className="icon" title="执行历史" onClick={()=>setScheduleHistory(t.id)}><History size={17}/></button><button className="icon" title="修改任务" onClick={()=>setScheduleEdit(t)}><Settings2 size={17}/></button><button className="icon" title={t.paused?'恢复':'暂停'} onClick={()=>{stopSchedule(t.id);change(s=>{const x=s.schedules.find(x=>x.id===t.id)!;x.paused=!x.paused;x.next=nextTime(x)})}}>{t.paused?<Play size={17}/>:<Pause size={17}/>}</button><button className="icon danger" title="删除任务" onClick={()=>{if(confirm('删除此定时任务？已有运行记录保留，之后不再执行。')){stopSchedule(t.id);change(s=>{s.schedules=s.schedules.filter(x=>x.id!==t.id)})}}}><Trash2 size={17}/></button></div></article>)}</div>:<div className="empty"><Clock3/><h3>把重复的事情，交给时间</h3><p>选择一个对话，设置提示词与频率。</p><button className="button secondary" onClick={()=>setScheduleEdit('new')}>创建第一个任务<Plus size={15}/></button></div>}</section>}
 {page==='trash'&&!chat&&<section className="page-section"><div className="page-heading"><div><span className="overline">A SECOND CHANCE</span><h1>回收站</h1><p>恢复项目，继续之前的想法。</p></div></div>{state.chats.some(c=>c.deleted)?<div className="trash-list">{state.chats.filter(c=>c.deleted).map(c=><div className="trash-row" key={c.id}><FileCode2 size={22}/><div><b>{c.title}</b><p>{c.versions.length} 个版本 · 已下线</p></div><button className="button secondary" onClick={()=>{change(s=>{s.chats.find(x=>x.id===c.id)!.deleted=false});notify('已恢复，定时任务仍保持暂停')} }><ArchiveRestore size={15}/>恢复</button><button className="icon danger" title="永久删除" onClick={()=>{if(confirm('永久删除“'+c.title+'”及全部聊天、版本和预览数据？此操作无法恢复。'))change(s=>{s.chats=s.chats.filter(x=>x.id!==c.id);s.schedules=s.schedules.filter(x=>x.chatId!==c.id);s.runs=s.runs.filter(x=>x.chatId!==c.id);s.notices=s.notices.filter(x=>x.chatId!==c.id)})}}><Trash2 size={16}/></button></div>)}</div>:<div className="empty"><Trash2/><h3>回收站是空的</h3><p>移入回收站的项目会显示在这里。</p></div>}</section>}
