 {notices&&<Modal title="通知" onClose={()=>setNotices(false)}><div className="history-list">{state.notices.map(n=><button className="execution-row" key={n.id} onClick={()=>{if(n.chatId)openChat(n.chatId);setNotices(false)}}><Bell size={16}/><div><b>{n.title}</b><p>{date(n.created)}</p></div></button>)}{!state.notices.length&&<div className="empty"><Bell/><p>一切安静，继续创造。</p></div>}</div></Modal>}
 {report&&<Modal title="研究报告" subtitle={date(report.created)} onClose={()=>setReport(null)} wide><div className="report-body"><Markdown text={report.content}/></div><div className="modal-footer"><button className="button secondary" onClick={()=>download('研究报告.md',report.content,'text/markdown;charset=utf-8')}><Download size={15}/>导出 Markdown</button><button className="button primary" onClick={()=>useReport(report)}><Sparkles size={15}/>基于报告构建</button></div></Modal>}
