function LoginModal({close,notify}:{close:()=>void;notify:(t:string)=>void}){
 const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[register,setRegister]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);try{await api(register?'/auth/register':'/auth/login',{email,password});location.reload()}catch(e){notify(errorText(e))}finally{setBusy(false)}}
 return <Modal title={register?'注册账号':'邮箱登录'} subtitle="邮箱不会经过验证，请妥善保管密码。" onClose={close}><form onSubmit={submit} className="settings-body"><label>邮箱<input type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/></label><label>密码<input type="password" required minLength={10} maxLength={256} autoComplete={register?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)}/></label><p className="fine-print">密码至少 10 个字符。当前不支持邮箱找回密码。</p><button className="button primary" disabled={busy}>{busy?'处理中…':register?'注册并登录':'登录'}</button><button type="button" className="button secondary" onClick={()=>setRegister(!register)}>{register?'已有账号？去登录':'没有账号？注册'}</button></form></Modal>
}

function SetPasswordModal({close,notify}:{close:()=>void;notify:(t:string)=>void}){
 const [password,setPassword]=useState(''),[busy,setBusy]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);try{await api('/auth/set-password',{password});location.reload()}catch(e){notify(errorText(e))}finally{setBusy(false)}}
 return <Modal title="为现有账号设置密码" subtitle="旧的邮件登录即将停用，请在当前已登录设备设置密码后再退出。" onClose={close}><form onSubmit={submit} className="settings-body"><label>新密码<input type="password" autoComplete="new-password" required minLength={10} maxLength={256} value={password} onChange={e=>setPassword(e.target.value)}/></label><p className="fine-print">密码至少 10 个字符；当前不支持邮箱找回。</p><button className="button primary" disabled={busy}>{busy?'保存中…':'设置密码'}</button></form></Modal>
}

function SettingsModal({close,notify}:{close:()=>void;notify:(s:string)=>void}){
 const state=useStore(),account=getAccount(),[section,setSection]=useState('models'),[editing,setEditing]=useState<string|null>(null),[testing,setTesting]=useState(false);
 const blank=():Profile=>({id:uid(),name:'',provider:'openai',protocol:'openai',base_url:providers[0].base,model:'',key:''});
 const [form,setForm]=useState<Profile>(blank),[showKey,setShowKey]=useState(false),[includeKeys,setIncludeKeys]=useState(false);const importInput=useRef<HTMLInputElement>(null);
 async function save(e:React.FormEvent){e.preventDefault();if(!form.model.trim()||(!form.key.trim()&&(!account||!editing))||!form.base_url.startsWith('https://')){notify('请填写 HTTPS 接口地址、模型名称和 API Key');return}const p={...form,name:form.name.trim()||providers.find(p=>p.id===form.provider)?.name+' · '+form.model};try{if(account){await saveCloudProfile(p);change(s=>{s.profileId=p.id})}else change(s=>{s.profiles=editing?s.profiles.map(x=>x.id===editing?p:x):[...s.profiles,p];s.profileId=p.id});setEditing(null);setForm(blank());notify(account?'模型配置已加密保存':'模型配置已保存到当前浏览器')}catch(e){notify('模型配置未保存：'+errorText(e))}}
 async function removeProfile(p:Profile){if(!confirm('删除此模型配置？相关定时任务将暂停。'))return;try{if(account)await deleteCloudProfile(p.id);state.schedules.filter(t=>t.profileId===p.id).forEach(t=>stopSchedule(t.id));change(s=>{s.profiles=s.profiles.filter(x=>x.id!==p.id);if(s.profileId===p.id)s.profileId=s.profiles[0]?.id||'';for(const t of s.schedules)if(t.profileId===p.id)t.paused=true})}catch(e){notify('删除失败：'+errorText(e))}}
 async function migrate(){const x=guestMigrationPreview();if(!confirm(`将本地记录追加到当前账号？\n对话 ${x.chats}，源码版本 ${x.versions}，研究报告 ${x.reports}，文件夹 ${x.folders}，运行 ${x.runs}，定时任务 ${x.schedules}，通知 ${x.notices}。\n对话预览：${x.titles.join("、")||"无"}${x.chats>10?"等":""}。\n不迁移 ${x.profiles} 个模型密钥和应用预览数据；定时任务导入后暂停。原本地数据保留，云端同编号记录会阻止迁移。`))return;try{await migrateGuest();notify('本地记录已追加到云端；请重新配置模型和定时任务')}catch(e){notify('迁移失败，云端未覆盖：'+errorText(e))}}
 async function restore(file:File){try{if(account)throw Error('云端账号请使用本地记录迁移，备份恢复仅支持游客工作空间');if(file.size>10_000_000)throw Error('备份文件超过 10 MB');const data=JSON.parse(await file.text()) as State;if(data.schema!==1||!Array.isArray(data.chats)||!Array.isArray(data.profiles)||!Array.isArray(data.folders)||!Array.isArray(data.schedules)||!Array.isArray(data.runs)||!Array.isArray(data.notices))throw Error('不是有效的 Atmos 工作空间备份');for(const c of data.chats)if(!Array.isArray(c.versions)||!Array.isArray(c.messages)||!c.previewData)throw Error('项目数据格式不正确');if(!confirm('导入会替换当前工作空间，是否继续？建议先导出当前备份。'))return;for(const r of getState().runs.filter(r=>r.status==='running'))stopRun(r.id);for(const r of data.runs)if(r.status==='running')r.status='cancelled';replace(data);notify('工作空间已恢复')}catch(e){notify(errorText(e))}}
 return <Modal title="工作空间设置" subtitle="你的模型，你的数据，你的创造方式。" onClose={close} wide><div className="settings-tabs"><button className={section==='models'?'selected':''} onClick={()=>setSection('models')}><KeyRound size={15}/>模型与 API</button><button className={section==='data'?'selected':''} onClick={()=>setSection('data')}><Database size={15}/>本地数据</button></div>{section==='models'?<div className="settings-body"><div className="info-banner"><KeyRound size={16}/><span>{account?'模型 Key 由服务端加密保存，调用由 Python 代理发起，费用由你的厂商账号承担。':'游客凭证保存在当前浏览器，调用时发送给 Python 代理和模型厂商。'}</span></div>{state.profiles.length>0&&<div className="profile-list">{state.profiles.map(p=><div className={'profile-row '+(state.profileId===p.id?'current':'')} key={p.id}><span className="model-initial">{p.name.slice(0,1).toUpperCase()}</span><button onClick={()=>change(s=>{s.profileId=p.id})}><b>{p.name}</b><small>{p.model} · {p.key_last4?'•••• '+p.key_last4:p.key?'•••• '+p.key.slice(-4):'需要重新填写凭证'}</small></button>{state.profileId===p.id&&<CheckCircle2 size={16}/>}<button className="icon" title="编辑模型" onClick={()=>{setForm({...p});setEditing(p.id)}}><Settings2 size={15}/></button><button className="icon danger" title="删除模型" onClick={()=>void removeProfile(p)}><Trash2 size={15}/></button></div>)}</div>}<form onSubmit={save} className="model-form"><h3>{editing?'编辑模型':'添加模型'}</h3><div className="form-grid"><label>模型厂商<select value={form.provider} onChange={e=>{const p=providers.find(p=>p.id===e.target.value)!;setForm({...form,provider:p.id,protocol:p.protocol,base_url:p.base})}}>{providers.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>配置名称<input placeholder="例如：日常构建" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label className="full">API 地址<input required type="url" placeholder="https://api.example.com/v1" value={form.base_url} onChange={e=>setForm({...form,base_url:e.target.value})}/></label><label>模型名称<input required placeholder="填写账号已开通的模型名称" value={form.model} onChange={e=>setForm({...form,model:e.target.value})}/></label><label>接口协议<select value={form.protocol} onChange={e=>setForm({...form,protocol:e.target.value})}><option value="openai">OpenAI 兼容</option><option value="anthropic">Anthropic Messages</option></select></label><label className="full">API Key<div className="key-field"><input required={!account||!editing} type={showKey?'text':'password'} autoComplete="off" placeholder={account&&editing?'留空保留原 Key，填写则替换':'输入你的 API Key'} value={form.key} onChange={e=>setForm({...form,key:e.target.value})}/><button type="button" className="icon" aria-label="显示或隐藏密钥" onClick={()=>setShowKey(!showKey)}><Eye size={16}/></button></div></label></div><div className="form-actions"><span>连接测试会实际调用模型。</span><button type="button" className="button secondary" disabled={testing||!form.model||(!form.key&&!(account&&editing))} onClick={async()=>{setTesting(true);try{const r=account&&editing&&!form.key?await testCloudProfile(editing):await api('/test',form);notify('连接成功：'+r.response)}catch(e){notify(errorText(e))}finally{setTesting(false)}}}>{testing?<LoaderCircle className="spin" size={14}/>:<Globe size={14}/>}测试连接</button><button className="button primary" type="submit"><Check size={15}/>{editing?'保存修改':'保存模型'}</button></div>{editing&&<button type="button" className="text-button" onClick={()=>{setEditing(null);setForm(blank())}}>取消编辑</button>}</form></div>:<div className="settings-body"><div className="data-overview"><Database size={28}/><div><h3>{account?'云端工作空间':'游客本地工作空间'}</h3><p>{account?'平台记录同步到账号；应用预览业务数据保留在此浏览器。':'刷新保留数据，换浏览器不会同步。'}</p></div></div><div className="stats-grid"><div><b>{state.chats.length}</b><span>对话</span></div><div><b>{state.chats.reduce((n,c)=>n+c.versions.length,0)}</b><span>代码版本</span></div><div><b>{(new Blob([JSON.stringify(state)]).size/1024).toFixed(0)} KB</b><span>本地使用量</span></div></div>{account&&<div className="backup-section"><h3>迁移本地平台记录</h3><p>先预览数量并确认，再追加到当前账号；不会上传本地模型 Key 或应用业务数据。</p><button className="button secondary" onClick={()=>void migrate()}>预览并迁移本地记录</button></div>}<div className="backup-section"><h3>工作空间备份</h3><p>备份包含聊天、版本、预览数据、定时任务及发布管理权限。</p>{!account&&<label className="checkbox"><input type="checkbox" checked={includeKeys} onChange={e=>setIncludeKeys(e.target.checked)}/>同时包含模型 API Key（敏感信息）</label>}<div><button className="button primary" onClick={()=>{const copy=structuredClone(state);if(!includeKeys)copy.profiles.forEach(p=>p.key='');download('atmos-workspace-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(copy,null,2),'application/json')}}><Download size={15}/>导出备份</button><button className="button secondary" onClick={()=>importInput.current?.click()}><Upload size={15}/>恢复备份</button><input ref={importInput} type="file" accept=".json" hidden onChange={e=>{if(e.target.files?.[0])void restore(e.target.files[0]);e.target.value=''}}/></div></div></div>}</Modal>
}

function ExportModal({chat,version,close,notify}:{chat:Chat;version:Version;close:()=>void;notify:(text:string)=>void}){const [data,setData]=useState(false);return <Modal title="导出 HTML" subtitle={'v'+version.number+' · 一个文件，独立使用。'} onClose={close}><div className="export-body"><div className="export-file"><FileCode2 size={30}/><div><b>{chat.title}.html</b><span>内联 HTML、CSS 与 JavaScript</span></div><span>{(version.html.length/1024).toFixed(1)} KB</span></div><button className={'option-card '+(!data?'selected':'')} onClick={()=>setData(false)}><span className="radio"/><div><b>空模板</b><p>保留完整功能，不带当前预览中的记录。</p></div>{!data&&<Check size={17}/>}</button><button className={'option-card '+(data?'selected':'')} onClick={()=>setData(true)}><span className="radio"/><div><b>带预览数据</b><p>附带当前预览记录，打开文件后作为初始数据。</p></div>{data&&<Check size={17}/>}</button><p className="fine-print">数据继续保存在使用者自己的浏览器，不包含平台聊天和模型凭证。</p></div><div className="modal-footer"><button className="button secondary" onClick={close}>取消</button><button className="button primary" onClick={()=>{try{download((chat.title.replace(/[\\/:*?"<>|\x00-\x1f]/g,'-').trim()||'atmos-app')+'.html',exportHtml(chat,version,data));close()}catch{notify('无法启动下载，请检查浏览器下载权限后重试')}}}><Download size={16}/>下载 HTML</button></div></Modal>}

function PublishModal({chat,version,close,notify}:{chat:Chat;version:Version;close:()=>void;notify:(t:string)=>void}){
 const [data,setData]=useState(false),[busy,setBusy]=useState(false),[url,setUrl]=useState(chat.publication?.url||'');
 async function publish(){setBusy(true);try{const publication=chat.publication||{id:uid(),secret:uid()+uid(),url:'',versionId:''};const result=await api('/publications/'+publication.id,{html:version.html,title:chat.title,secret:publication.secret,data:data?chat.previewData:{}},'PUT');change(s=>{s.chats.find(c=>c.id===chat.id)!.publication={...publication,url:result.url,versionId:version.id}});setUrl(result.url);notify('已发布所选版本')}catch(e){notify(errorText(e))}finally{setBusy(false)}}
 return <Modal title="发布应用" subtitle={'将 v'+version.number+' 放到一个可访问的链接中。'} onClose={close}><div className="export-body"><div className="publish-illustration"><Globe size={32}/><span className="pill">HTML 应用</span></div><h3>{chat.title}</h3><label className="checkbox"><input type="checkbox" checked={data} onChange={e=>setData(e.target.checked)}/>将当前预览数据一起公开为初始数据</label><p className="fine-print">只上传所选 HTML 与勾选的数据。聊天、密钥和历史版本留在本地。访问者的后续操作保存在其自己的浏览器。</p>{url&&<div className="published-link"><a href={url} target="_blank" rel="noopener noreferrer">{url}</a><button className="icon" title="复制发布链接" onClick={()=>void navigator.clipboard.writeText(url).then(()=>notify('链接已复制')).catch(()=>notify('请手动复制链接'))}><Copy size={16}/></button></div>}</div><div className="modal-footer"><button className="button secondary" onClick={close}>关闭</button><button className="button primary" disabled={busy} onClick={()=>void publish()}>{busy?<LoaderCircle className="spin" size={15}/>:<Globe size={15}/>} {url?'更新发布版本':'发布并获取链接'}</button></div></Modal>
}

function ScheduleModal({value,currentChat,close,notify}:{value:Schedule|'new';currentChat:string|null;close:()=>void;notify:(t:string)=>void}){
 const state=useStore();const [form,setForm]=useState<Schedule>(value==='new'?{id:uid(),chatId:currentChat||state.chats.find(c=>!c.deleted)?.id||'',name:'',prompt:'',profileId:state.profileId||state.profiles[0]?.id||'',frequency:'daily',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai',at:'09:00',weekday:0,day:1,month:1,paused:false,next:0,notifySuccess:true,notifyFailure:true}:{...value});
 const patch=(key:string,v:any)=>setForm({...form,[key]:v});let next='';try{next=new Date(nextTime(form)).toLocaleString('zh-CN',{timeZone:form.timezone})}catch{}
 function save(e:React.FormEvent){e.preventDefault();try{if(!form.chatId||!form.profileId||!form.name.trim()||!form.prompt.trim())throw Error('请填写名称、对话、模型和检查内容');const item={...form,next:nextTime(form)};stopSchedule(item.id);change(s=>{s.schedules=value==='new'?[...s.schedules,item]:s.schedules.map(x=>x.id===item.id?item:x)});close();notify('定时任务已保存，页面打开时自动检查')}catch(e){notify(errorText(e))}}
 return <Modal title={value==='new'?'创建定时任务':'编辑定时任务'} subtitle="当前对话的自动化检查，不修改代码或发布内容。" onClose={close} wide><form onSubmit={save}><div className="settings-body"><div className="form-grid"><label className="full">任务名称<input required maxLength={100} value={form.name} onChange={e=>patch('name',e.target.value)} placeholder="为这次重复检查起个名字"/></label><label>所属对话<select required value={form.chatId} onChange={e=>patch('chatId',e.target.value)}><option value="">选择一个对话</option>{state.chats.filter(c=>!c.deleted).map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label>使用模型<select required value={form.profileId} onChange={e=>patch('profileId',e.target.value)}><option value="">选择模型配置</option>{state.profiles.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className="full">每次运行要检查的内容<textarea required rows={4} value={form.prompt} onChange={e=>patch('prompt',e.target.value)} placeholder="明确要查看哪些公开资料、检查什么变化，以及如何汇报。"/></label><label>频率<select value={form.frequency} onChange={e=>patch('frequency',e.target.value)}>{Object.entries(frequencyNames).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>{form.frequency==='hourly'?'每小时的分钟':'执行时间'}<input required type="time" value={form.at} onChange={e=>patch('at',e.target.value)}/></label>{form.frequency==='weekly'&&<label>星期<select value={form.weekday} onChange={e=>patch('weekday',+e.target.value)}>{['一','二','三','四','五','六','日'].map((x,i)=><option key={i} value={i}>星期{x}</option>)}</select></label>}{['monthly','yearly'].includes(form.frequency)&&<label>日期<input type="number" min={1} max={31} value={form.day} onChange={e=>patch('day',+e.target.value)}/></label>}{form.frequency==='yearly'&&<label>月份<input type="number" min={1} max={12} value={form.month} onChange={e=>patch('month',+e.target.value)}/></label>}<label className={form.frequency==='daily'||form.frequency==='hourly'?'full':''}>时区<input required value={form.timezone} onChange={e=>patch('timezone',e.target.value)} placeholder="Asia/Shanghai"/></label></div><div className="schedule-preview"><Clock3 size={16}/><span>下次执行：{next||'请检查时间和时区'}</span></div><div className="notification-options"><span>站内通知</span><label className="checkbox"><input type="checkbox" checked={form.notifySuccess} onChange={e=>patch('notifySuccess',e.target.checked)}/>检查完成</label><label className="checkbox"><input type="checkbox" checked={form.notifyFailure} onChange={e=>patch('notifyFailure',e.target.checked)}/>检查失败</label></div><p className="fine-print">仅检查与汇报。会将本对话的记录及预览数据作为只读上下文发送给所选模型。关闭或刷新页面会中断运行；错过不补跑。月末日期不存在时取最后一天。</p></div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>取消</button><button type="submit" disabled={!next} className="button primary"><Check size={15}/>保存任务</button></div></form></Modal>
}

const publicMatch=location.pathname.match(/^\/p\/([a-f0-9]{32})$/),privateMatch=location.pathname.match(/^\/view\/([a-f0-9]{32})\/([a-f0-9]{32})$/);
void initialize().then(()=>createRoot(document.getElementById('root')!).render(publicMatch?<Viewer id={publicMatch[1]}/>:privateMatch?<Viewer id={privateMatch[1]} privateVersion={privateMatch[2]}/>:<App/>)).catch(e=>{document.getElementById('root')!.textContent='云端工作空间无法读取，请检查网络后刷新：'+errorText(e)});
